    private final long maxTokens;

    /**
     * Скорость пополнения ведра в токенах в миллисекунду.
     * Например, если нужно 10 токенов в секунду, то ratePerMs = 10.0 / 1000.0 = 0.01.
     * Хранится как double для точности при дробных скоростях пополнения.
     */
    private final double refillRatePerMs;

