impl LineIterator {
    /// Создаёт новый итератор по строкам для файла по указанному пути.
    ///
    /// Открывает файл и инициализирует буферизированный читатель.
    ///
    /// # Аргументы
    /// * `path` — путь к файлу, который нужно читать построчно.
    ///
    /// # Возвращает
    /// * `Ok(LineIterator)` — успешно созданный итератор.
    /// * `Err(io::Error)` — ошибка при открытии файла.
    ///
    /// # Пример
    /// ```no_run
    /// use std::path::Path;
    ///
    /// let iter = LineIterator::new(Path::new("example.txt")).unwrap();
    /// ```
    pub fn new<P: AsRef<Path>>(path: P) -> io::Result<Self> {
        let file = File::open(path)?;
        // Используем BufReader с увеличенным буфером для лучшей производительности
        // при чтении больших файлов. Стандартный размер буфера BufReader — 8 КБ,
        // но для больших файлов можно увеличить его.
        let reader = BufReader::with_capacity(64 * 1024, file);
        Ok(LineIterator {
            reader,
            buffer: Vec::with_capacity(1024),
            eof: false,
        })
