public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл повторных попыток выполнения действия.
    // Переменная i отслеживает номер текущей попытки (от 0 до attempts - 1).
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить асинхронное действие action().
            // Если действие завершается успешно, возвращаем его результат и выходим из метода.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Если возникло исключение HttpRequestException и это не последняя попытка,
            // делаем паузу перед следующей попыткой.
            // Задержка растёт экспоненциально: 200 мс * 2^i (backoff strategy).
            // Это помогает избежать перегрузки сервера при частых повторных запросах.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
        // Если исключение не HttpRequestException или это последняя попытка,
        // исключение пробрасывается выше (не перехватывается).
    }

    // Этот код теоретически недостижим, так как:
