```typescript
/**
 * Функция debounce (задержка выполнения).
 * Возвращает новую функцию, которая откладывает вызов оригинальной функции `fn`
 * на указанное количество миллисекунд (`ms`). Если новая функция вызывается
 * повторно до истечения таймера, предыдущий отложенный вызов отменяется,
 * и таймер перезапускается.
 *
 * @param fn - Оригинальная функция, которую нужно "задержать".
 * @param ms - Количество миллисекунд задержки.
 * @returns Новая функция с тем же типом аргументов, что и оригинальная.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера setTimeout.
  // Инициализируется как undefined, так как таймер еще не установлен.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию-обертку.
  // Она принимает те же аргументы, что и оригинальная функция `fn`,
  // благодаря использованию типа Parameters<T>.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен (переменная t не undefined),
    // отменяем предыдущий отложенный вызов, чтобы он не выполнился.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер на `ms` миллисекунд.
    // По истечении этого времени будет вызвана оригинальная функция `fn`
    // с последними переданными аргументами.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

