/// Разбирает строку формата "ключ1=значение1;ключ2=значение2;..." в HashMap.
/// Ключи приводятся к нижнему регистру и обрезаются по краям, значения также обрезаются.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // Разбиваем входную строку по символу ';' на отдельные пары "ключ=значение"
        .filter_map(|p| p.split_once('=')) // Для каждой части пытаемся разделить её по первому '=';
                                           // если '=' нет, часть игнорируется (filter_map отбрасывает None)
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // Обрезаем пробелы вокруг ключа и значения,
                                                                       // приводим ключ к нижнему регистру,
                                                                       // а значение оставляем как есть (но тоже обрезаем)
        .collect() // Собираем все пары (ключ, значение) в HashMap
}
